package mclite;
import javax.imageio.ImageIO; import javax.swing.*; import java.awt.*; import java.awt.image.*; import java.io.*;
public class LaunchProgressTest { public static void main(String[] a)throws Exception{ SwingUtilities.invokeAndWait(()->{ JFrame owner=new JFrame(); owner.setSize(200,100); owner.setVisible(true); var d=new LaunchProgress(owner,"僵尸启示录"); d.setVisible(true); d.stage("检查 mods / 资源包…"); Timer t=new Timer(700,e->{ try{ var img=new BufferedImage(d.getContentPane().getWidth(),d.getContentPane().getHeight(),BufferedImage.TYPE_INT_RGB); var g=img.createGraphics(); d.getContentPane().paint(g); g.dispose(); ImageIO.write(img,"png",new File("build/launch-progress.png")); }catch(Exception ex){ex.printStackTrace();} d.dispose(); owner.dispose(); System.exit(0); }); t.setRepeats(false); t.start(); }); } }
